This builds the answer independently by simulating the bucket one time step at a time and compares it with `result`. A token arriving at time `step` is added before any request at that same `step` is served, as the docstring requires.

```python
def pre(times):
    if len(times) > 6:
        return False
    for t in times:
        if t < 0 or t > 16:
            return False
    for i in range(len(times) - 1):
        if times[i] > times[i + 1]:
            return False
    return True


def expected_admits(times):
    tokens = 3
    admitted = 0
    for step in range(17):
        # Tokens arrive at 4, 8, 12, 16 before requests at the same time.
        if step > 0 and step % 4 == 0:
            if tokens < 3:
                tokens += 1
        for t in times:
            if t == step:
                if tokens > 0:
                    tokens -= 1
                    admitted += 1
    return admitted


def post(times, result):
    return result == expected_admits(times)
